() => {
  // Find elements containing "Something went wrong"
  const allElements = document.querySelectorAll('*');
  const results = [];
  for (const el of allElements) {
    if (el.textContent.includes('Something went wrong') && el.children.length === 0) {
      results.push({
        tag: el.tagName,
        text: el.textContent.trim(),
        className: el.className,
        parentClass: el.parentElement?.className,
        grandparentClass: el.parentElement?.parentElement?.className,
        id: el.id
      });
    }
  }
  return results;
}

() => {
  // Find the "Something went wrong" element and get more context about its surrounding area
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    if (el.textContent === 'Something went wrong' && el.children.length === 0) {
      // Walk up the DOM tree to find the project card
      let current = el;
      const ancestors = [];
      for (let i = 0; i < 10; i++) {
        current = current.parentElement;
        if (!current) break;
        ancestors.push({
          tag: current.tagName,
          className: current.className,
          id: current.id,
          role: current.getAttribute('role'),
          dataAttrs: Array.from(current.attributes).filter(a => a.name.startsWith('data-')).map(a => `${a.name}=${a.value}`),
          childCount: current.children.length,
          outerHTMLLength: current.outerHTML.length
        });
      }

      // Also get the sibling context
      const parent = el.parentElement;
      const siblings = parent ? Array.from(parent.children).map(c => ({
        tag: c.tagName,
        text: c.textContent?.substring(0, 100),
        className: c.className
      })) : [];

      return { ancestors, siblings };
    }
  }
  return null;
}
